mapper.select:
SELECT id, tenant_id, user_id, username, module, operation,
       description, request_method, request_url, request_params, ip,
       status, error_msg, cost_time_ms, target_type, target_id, target_summary, create_time
FROM audit_log
WHERE 1 = 1

    AND tenant_id = #{tenantId}


    AND module = #{module}


    AND operation = #{operation}


    AND (
        username LIKE CONCAT('%', #{username}, '%')
        OR CAST(user_id AS CHAR) = #{username}
        OR user_id IN (
            SELECT id FROM `user`
            WHERE is_deleted = 0
              AND real_name LIKE CONCAT('%', #{username}, '%')
        )
    )


    AND status = #{status}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

ORDER BY id DESC
